xql_query:
// ============================================================
// Rule: WIN_Process from GitHub Desktop
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_Process from GitHub Desktop.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Technique: T1204.002 - User Execution: Malicious File

// Configuração inicial: define que as comparações de strings não diferenciam maiúsculas/minúsculas
config case_sensitive = false  

// Fonte de dados: eventos coletados pelo Cortex XDR
| dataset = xdr_data  

// Filtro para selecionar apenas eventos de processo
// - event_type = PROCESS → eventos de processo
// - event_sub_type = PROCESS_START → início de execução de processo
| filter event_type = ENUM.PROCESS and event_sub_type = ENUM.PROCESS_START  

// Filtro adicional: mantém apenas processos que possuem marcação de origem web
// (informações sobre de onde o binário foi baixado/aberto)
| filter action_process_file_web_mark != null  

// Criação de campos derivados a partir do metadado de origem web
| alter HostUrl = action_process_file_web_mark -> HostUrl        // Host de onde o arquivo foi obtido
| alter ReferrerUrl = action_process_file_web_mark -> ReferrerUrl // URL de referência que direcionou o download  

// Filtro específico: processos iniciados a partir de arquivos cuja URL de referência
// contém o repositório GitHub Desktop
| filter ReferrerUrl contains "github.com/desktop/desktop/tree"  

// Seleção de campos relevantes para análise
| fields agent_hostname,                        // Host onde ocorreu a execução
         actor_effective_username,              // Usuário logado que executou o processo
         action_process_file_web_mark,          // Metadados da origem web do binário
         action_process_image_path,             // Caminho do executável iniciado
         action_process_image_command_line,     // Linha de comando do processo iniciado
         actor_process_image_path,              // Caminho do processo pai
         actor_process_command_line,            // Linha de comando do processo pai
         causality_actor_process_image_path,    // Caminho do processo de causalidade
         causality_actor_process_command_line   // Linha de comando do processo de causalidade
